import CMigration
import Darwin
import zlib

extension gzip {
  /*
   * compress the given file: create a corresponding .gz file and remove the
   * original.
   */
  func file_compress(_ file : String, _ outfile : String, _ outsize : size_t) -> off_t {
    //   int in;
    //    int out;
    //    off_t size, in_size;

    //    struct stat isb, osb;
    //    const suffixes_t *suff;

    guard let inx = try? FileDescriptor.open(file, .readOnly) else {
      maybe_warn("can't open \(file)")
      return -1
    }

    defer { try? inx.close() }

    //    bzero(&isb, sizeof(isb));
    guard let isb = try? FileMetadata(for: inx) else {
      maybe_warn("couldn't stat: \(file)")
      return -1
    }

    r.infile = file
    r.infile_total = isb.size

    if !options.cflag {
      if isb.links > 1 && !options.fflag {
        maybe_warnx("\(file) has \(isb.links-1) other link\(isb.links == 2 ? "" : "s") -- skipping")
        return -1
      }

      if (!options.fflag && (suff = check_suffix(file, 0)) &&
          suff->zipped[0] != 0) {
        maybe_warnx("\(file) already has \(suff.zipped) suffix -- unchanged")
        return -1
      }

      /* Add (usually) .gz to filename */
      if ((size_t)snprintf(outfile, outsize, "%s%s",
                           file, suffixes[0].zipped) >= outsize) {
        memcpy(outfile + outsize - suffixes[0].ziplen - 1,
               suffixes[0].zipped, suffixes[0].ziplen + 1);
      }

      if (check_outfile(outfile) == 0) {
        return -1
      }
    }

    if (!options.cflag) {
      out = open(outfile, O_WRONLY | O_CREAT | O_EXCL, 0600);
      if (out == -1) {
        maybe_warn("could not create output: %s", outfile);
        fclose(stdin);
        return (-1);
      }

      remove_file = outfile;
    } else {
      out = STDOUT_FILENO;
    }

    in_size = gz_compress(in, out, &size, basename(file), (uint32_t)isb.st_mtime);

    /*
     * If there was an error, in_size will be -1.
     * If we compressed to stdout, just return the size.
     * Otherwise stat the file and check it is the correct size.
     * We only blow away the file if we can stat the output and it
     * has the expected size.
     */
    if options.cflag {
      return in_size == -1 ? -1 : size;
    }

    if (fstat(out, &osb) != 0) {
      maybe_warn("couldn't stat: %s", outfile);
      goto bad_outfile;
    }

    if (osb.st_size != size) {
      maybe_warnx("output file: %s wrong size (%ju != %ju), deleting",
                  outfile, (uintmax_t)osb.st_size, (uintmax_t)size);
      goto bad_outfile;
    }

    fcopyfile(in, out, 0, COPYFILE_ACL | COPYFILE_XATTR);
    clear_type_and_creator(out);

    copymodes(out, &isb, outfile);
    remove_file = NULL;

    close(in);
    if (close(out) == -1) {
      maybe_warn("couldn't close output");
    }

    /* output is good, ok to delete input */
    unlink_input(file, &isb);
    return (size);

  bad_outfile:
    if (close(out) == -1) {
      maybe_warn("couldn't close output");
    }

    maybe_warnx("leaving original \(file)")
    unlink(outfile)
    return (size)
  }

  /* uncompress the given file and remove the original */
  func file_uncompress(_ file : String, _ outfile : String, _ outsize : size_t) -> off_t {
    /*    struct stat isb, osb;
     off_t size;
     ssize_t rbytes;
     unsigned char fourbytes[4];
     enum filetype method;
     int fd, ofd, zfd = -1;
     int error;
     size_t in_size;

     ssize_t rv;
     time_t timestamp = 0;
     char name[PATH_MAX + 1];
     */

    /* gather the old name info */

    guard let fd = try? FileDescriptor.open(file, .readOnly) else {
      maybe_warn("can't open \(file)")
      return -1
    }
    defer { try? fd.close() }

    guard let isb = try? FileMetadata(for: fd) else {
      maybe_warn("can't stat \(file)")
      return -1
    }

    var in_size = isb.filetype == .regular ? isb.size : 0
    r.infile = file
    r.infile_total = in_size

    strlcpy(outfile, file, outsize);
    if (check_suffix(outfile, 1) == NULL && !(options.cflag || options.lflag)) {
      maybe_warnx("%s: unknown suffix -- ignored", file);
      goto lose;
    }

    let fourbytes = try? fd.readUpToCount(4)
    if fourbytes?.count ?? -1 != 4 {
      /* we don't want to fail here. */

      if options.fflag {
        return -1
      }
      if fourbytes == nil {
        maybe_warn("can't read \(file)")
      }
      else {
        goto unexpected_EOF;
      }
      return -1
    }

    r.infile_current += rbytes

    let method = file_gettype(fourbytes);

    if (!options.fflag && method == .UNKNOWN) {
      maybe_warnx("%s: not in gzip format", file);
      goto lose;
    }

    if (method == .GZIP && options.Nflag) {
      unsigned char ts[4];  /* timestamp */

      rv = pread(fd, ts, sizeof ts, GZIP_TIMESTAMP);
      if (rv >= 0 && rv < (ssize_t)(sizeof ts)) {
        goto unexpected_EOF;
      }
      if (rv == -1) {
        if (!options.fflag) {
          maybe_warn("can't read %s", file);
        }
        goto lose;
      }
      infile_newdata(rv);
      timestamp = le32dec(&ts[0]);

      if (fourbytes[3] & ORIG_NAME) {
        rbytes = pread(fd, name, sizeof(name) - 1, GZIP_ORIGNAME);
        if (rbytes < 0) {
          maybe_warn("can't read %s", file);
          goto lose;
        }
        if (name[0] != '\0') {
          char *dp, *nf;

          /* Make sure that name is NUL-terminated */
          name[rbytes] = '\0';

          /* strip saved directory name */
          nf = strrchr(name, '/');
          if (nf == NULL) {
            nf = name;
          }
          else {
            nf++;
          }

          /* preserve original directory name */
          dp = strrchr(file, '/');
          if (dp == NULL) {
            dp = file;
          }
          else {
            dp++;
          }
          snprintf(outfile, outsize, "%.*s%.*s",
                   (int) (dp - file),
                   file, (int) rbytes, nf);
        }
      }
    }

    lseek(fd, 0, SEEK_SET);

    if (!options.cflag || options.lflag) {

      if (isb.st_nlink > 1 && !options.lflag && !options.fflag) {
        maybe_warnx("%s has %ju other links -- skipping",
                    file, (uintmax_t)isb.st_nlink - 1);
        goto lose;
      }
      if (!options.nflag && timestamp) {
        isb.st_mtime = timestamp;
      }
      if (check_outfile(outfile) == 0) {
        goto lose;
      }
    }

    if (options.cflag) {
      zfd = STDOUT_FILENO;
    }
    else if (options.lflag) {
      zfd = -1;
    }
    else {
      zfd = open(outfile, O_WRONLY|O_CREAT|O_EXCL, 0600);
      if (zfd == STDOUT_FILENO) {
        /* We won't close STDOUT_FILENO later... */
        zfd = dup(zfd);
        close(STDOUT_FILENO);
      }
      if (zfd == -1) {
        maybe_warn("can't open %s", outfile);
        goto lose;
      }
      remove_file = outfile;
    }

    switch (method) {

      case .BZIP2:
        /* XXX */
        if (options.lflag) {
          maybe_warnx("no -l with bzip2 files");
          goto lose;
        }

        size = unbzip2(fd, zfd, NULL, 0, NULL);
        break;

      case .Z: {
        FILE *in, *out;

        /* XXX */
        if (options.lflag) {
          maybe_warnx("no -l with Lempel-Ziv files");
          goto lose;
        }

        if ((in = zdopen(fd)) == NULL) {
          maybe_warn("zdopen for read: %s", file);
          goto lose;
        }

        out = fdopen(dup(zfd), "w");
        if (out == NULL) {
          maybe_warn("fdopen for write: %s", outfile);
          fclose(in);
          goto lose;
        }

        size = zuncompress(in, out, NULL, 0, NULL);
        /* need to fclose() if ferror() is true... */
        error = ferror(in);
        if (error | fclose(in)) {
          if (error) {
            maybe_warn("failed infile");
          }
          else {
            maybe_warn("failed infile fclose");
          }
          if (!options.cflag) {
            unlink(outfile);
          }
          fclose(out);
          goto lose;
        }
        if (fclose(out) != 0) {
          maybe_warn("failed outfile fclose");
          if (!options.cflag) {
            unlink(outfile);
          }
          goto lose;
        }
        break;
      }

      case .PACK:
        if (options.lflag) {
          maybe_warnx("no -l with packed files");
          goto lose;
        }

        size = unpack(fd, zfd, NULL, 0, NULL);
        break;

      case .XZ:
        if (options.lflag) {
          size = unxz_len(fd);
          if (!options.tflag) {
            print_list_out(in_size, size, file);
            close(fd);
            return -1;
          }
        } else {
          size = unxz(fd, zfd, NULL, 0, NULL);
        }
        break;

      case .LZ:
        if (options.lflag) {
          maybe_warnx("no -l with lzip files");
          goto lose;
        }
        size = unlz(fd, zfd, NULL, 0, NULL);
        break;

      case .UNKNOWN:
        if (options.lflag) {
          maybe_warnx("no -l for unknown filetypes");
          goto lose;
        }
        size = cat_fd(NULL, 0, NULL, fd);
        break;

      default:
        if (options.lflag) {
          print_list(fd, in_size, outfile, isb.st_mtime);
          if (!options.tflag) {
            close(fd);
            return -1;  /* XXX */
          }
        }

        size = gz_uncompress(fd, zfd, NULL, 0, NULL, file);
        break;
    }

    if (close(fd) != 0) {
      maybe_warn("couldn't close input");
    }
    if (zfd != STDOUT_FILENO && close(zfd) != 0) {
      maybe_warn("couldn't close output");
    }

    if (size == -1) {
      if (!options.cflag) {
        unlink(outfile);
      }
      maybe_warnx("%s: uncompress failed", file);
      return -1;
    }

    /* if testing, or we uncompressed to stdout, this is all we need */

    if (options.tflag) {
      return size;
    }

    /* if we are uncompressing to stdin, don't remove the file. */
    if (options.cflag) {
      return size;
    }

    /*
     * if we create a file...
     */
    /*
     * if we can't stat the file don't remove the file.
     */

    ofd = open(outfile, O_RDWR, 0);
    if (ofd == -1) {
      maybe_warn("couldn't open (leaving original): %s",
                 outfile);
      return -1;
    }
    if (fstat(ofd, &osb) != 0) {
      maybe_warn("couldn't stat (leaving original): %s",
                 outfile);
      close(ofd);
      return -1;
    }
    if (osb.st_size != size) {
      maybe_warnx("stat gave different size: %ju != %ju (leaving original)",
                  (uintmax_t)size, (uintmax_t)osb.st_size);
      close(ofd);
      unlink(outfile);
      return -1;
    }

    copymodes(ofd, &isb, outfile);
    remove_file = NULL;

    close(ofd);
    unlink_input(file, &isb);
    return size;

  unexpected_EOF:
    maybe_warnx("%s: unexpected end of file", file);
  lose:
    if (fd != -1) {
      close(fd);
    }
    if (zfd != -1 && zfd != STDOUT_FILENO) {
      close(zfd);
    }
    return -1;
  }

  func check_siginfo() {
    if (print_info == 0) {
      return;
    }
    if (infile) {
      if (infile_total) {
        int pcent = (int)((100.0 * infile_current) / infile_total);

        fprintf(stderr, "%s: done %llu/%llu bytes %d%%\n",
                infile, (unsigned long long)infile_current,
                (unsigned long long)infile_total, pcent);
      } else {
        fprintf(stderr, "%s: done %llu bytes\n",
                infile, (unsigned long long)infile_current);
      }
    }
    print_info = 0;
  }

  func cat_fd(_ prepend : [UInt8], _ count : size_t, _ gsizep : inout off_t, _ fd : FileDescriptor) -> off_t {
    char buf[BUFLEN];
    off_t in_tot;
    ssize_t w;

    in_tot = count;
    w = write_retry(STDOUT_FILENO, prepend, count);
    if (w == -1 || (size_t)w != count) {
      maybe_warn("write to stdout");
      return -1;
    }
    while true {
      let rv = read(fd, buf, sizeof buf);
      if (rv == 0) {
        break;
      }
      if (rv < 0) {
        maybe_warn("read from fd \(fd.rawValue)")
        break;
      }

      r.infile_current += rv

      if (write_retry(STDOUT_FILENO, buf, rv) != rv) {
        maybe_warn("write to stdout");
        break;
      }
      in_tot += rv;
    }

    if (gsizep) {
      *gsizep = in_tot;
    }
    return (in_tot);
  }
}

